import{_ as s,o as i,c as t,aF as a}from"./chunks/framework.D18EJqJJ.js";const k=JSON.parse('{"title":"service-kfs","description":"Kalisio Features Services","frontmatter":{"title":"service-kfs","description":"Kalisio Features Services"},"headers":[],"relativePath":"packages/service-kfs/index.md","filePath":"packages/service-kfs/index.md"}'),o={name:"packages/service-kfs/index.md"};function r(n,e,l,d,c,h){return i(),t("div",null,[...e[0]||(e[0]=[a(`<h1 id="service-kfs" tabindex="-1">service-kfs <a class="header-anchor" href="#service-kfs" aria-label="Permalink to &quot;service-kfs&quot;">​</a></h1><p><em>Kalisio Features Services</em></p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p><strong>service-kfs</strong> is a lightweight service that distributes geospatial data from applications built with the <a href="https://kalisio.github.io/kdk/" target="_blank" rel="noreferrer">Kalisio Development Kit (KDK)</a> — such as <a href="https://kalisio.github.io/kano/" target="_blank" rel="noreferrer">Kano</a> — through the <a href="https://ogcapi.ogc.org/features/" target="_blank" rel="noreferrer">OGC API Features</a> standard (a.k.a. WFS v3).</p><p>Each service-based layer from Kano generates one or two feature collection(s), depending on whether probes are used.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Under the hood, <a href="https://github.com/kalisio/feathers-distributed" target="_blank" rel="noreferrer">feathers-distributed</a> is used to access the exposed services. The service itself is stateless — it holds no database and simply re-exposes the remote feature services it discovers.</p></div><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><p><strong>service-kfs</strong> implements the <a href="https://ogcapi.ogc.org/features/" target="_blank" rel="noreferrer">OGC API Features</a> standard (a.k.a. WFS v3). The full HTTP API is documented on the <a href="./service-kfs-openapi.html">API reference</a> page.</p><p>Refer to the <a href="https://ogcapi.ogc.org/features/" target="_blank" rel="noreferrer">OGC API Features</a> standard for the complete specification. Current limitations:</p><ul><li>only <strong>Part 1</strong> of the standard is implemented</li><li>only the <a href="https://docs.opengeospatial.org/is/17-069r4/17-069r4.html#_requirements_class_geojson" target="_blank" rel="noreferrer">GeoJSON encoding</a> is supported</li><li>only a <a href="https://docs.ogc.org/is/17-069r4/17-069r4.html#_parameter_bbox" target="_blank" rel="noreferrer">bbox in WGS 84 CRS</a> is supported</li><li>the following <a href="https://docs.ogc.org/is/21-065r2/21-065r2.html" target="_blank" rel="noreferrer">CQL2</a> filtering operators are supported: <ul><li>logical: <code>and</code>, <code>or</code>, <code>not</code></li><li>comparison: <code>eq</code>, <code>lt</code>, <code>gt</code>, <code>lte</code>, <code>gte</code>, <code>between</code>, <code>in</code>, <code>isNull</code></li><li>advanced comparison: <code>like</code>, <code>ilike</code></li><li>spatial: <code>s_intersects</code>, <code>s_within</code></li><li>temporal: <code>t_before</code>, <code>t_after</code>, <code>t_during</code> (targeting an instant property, not an interval)</li></ul></li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>CQL is fully supported only in the <strong>JSON</strong> encoding. In the <strong>text</strong> encoding, only the spatial (<code>S_INTERSECTS</code>, <code>S_WITHIN</code>), null (<code>IS NULL</code>, <code>IS NOT NULL</code>) and like (<code>LIKE</code>, <code>ILIKE</code>) filters are supported.</p></div><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>The service is configured through environment variables:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><code>HOSTNAME</code></td><td>Hostname</td><td><code>localhost</code></td></tr><tr><td><code>PORT</code></td><td>Port the API responds on</td><td><code>8081</code></td></tr><tr><td><code>BASE_URL</code></td><td>Base service URL used to fill links</td><td><code>http://\${HOSTNAME}:\${PORT}\${API_PREFIX}</code></td></tr><tr><td><code>API_PREFIX</code></td><td>Prefix used on API routes</td><td><code>/api</code></td></tr><tr><td><code>LIMIT</code></td><td>Default pagination limit</td><td><code>500</code></td></tr><tr><td><code>OFFSET</code></td><td>Default pagination offset</td><td><code>0</code></td></tr><tr><td><code>MAX</code></td><td>Maximum pagination limit. When set, it overrides <code>paginate.max</code> for all services.</td><td><code>null</code></td></tr><tr><td><code>TIME_UNIT</code></td><td>Time unit used to compute temporal collection extents</td><td><code>minute</code></td></tr><tr><td><code>DISTRIBUTION_TIMEOUT</code></td><td>feathers-distributed request timeout, in milliseconds</td><td><code>60000</code></td></tr><tr><td><code>DEBUG</code></td><td>Namespaces to enable debug output. Use <code>kfs:*</code> for full output.</td><td>–</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The pagination options of the FeathersJS services (<code>paginate.default</code>, <code>paginate.max</code>) are retrieved and compared with the KFS default limit. If a service&#39;s default or maximum limit is lower, it is used instead — requesting more data than a service allows would not work.</p></div><h3 id="local-cjs" tabindex="-1">local.cjs <a class="header-anchor" href="#local-cjs" aria-label="Permalink to &quot;local.cjs&quot;">​</a></h3><p>By default, <strong>service-kfs</strong> only exposes the <a href="https://kalisio.github.io/kdk/api/map/services.html#features-service" target="_blank" rel="noreferrer">features services</a> provided by <a href="https://kalisio.github.io/kano/" target="_blank" rel="noreferrer">Kano</a>. Add a <code>local.cjs</code> file to alter the default configuration.</p><p>The following example exposes services from another application:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">module</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">exports</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  distribution: {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // Application key in feathers-distributed</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    remoteServices</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: (</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">service</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (service.key </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">===</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;myapp&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // Declare any additional service that is not a features service but complies with the GeoJSON interface</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  services</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: (</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">serviceName</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">service</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // This specific service complies with a GeoJSON interface using specific query parameters</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (serviceName </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">===</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;myservice&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      query: { geoJson: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="running" tabindex="-1">Running <a class="header-anchor" href="#running" aria-label="Permalink to &quot;Running&quot;">​</a></h2><p>Start the service in watch mode for development:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>The API is then served at <code>http://localhost:8081/api</code>. The metadata endpoints (<code>/</code>, <code>/conformance</code>, <code>/definition</code>, <code>/healthcheck</code>) work out of the box; <code>/collections</code> becomes populated once an upstream application (e.g. Kano) distributes its feature services.</p><h2 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h2><p>Run the internal test suite:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The suite starts an in-process KDK app that stores fixtures, so it requires a MongoDB reachable at <code>mongodb://127.0.0.1:27017</code> (the test config auto-switches the host to <code>mongodb</code> when running inside a container).</p></div><p>To run the <a href="https://github.com/opengeospatial/ets-ogcapi-features10" target="_blank" rel="noreferrer">OGC API - Features Conformance Test Suite</a>, the simplest way is to use its <a href="https://github.com/opengeospatial/ets-ogcapi-features10/blob/master/src/site/asciidoc/how-to-run-the-tests.adoc#3-docker" target="_blank" rel="noreferrer">Docker container</a>. Use your machine&#39;s local IP address rather than <code>localhost</code> (which will not work) and start KFS with <code>HOSTNAME=your_ip</code>.</p><p>You can also run it manually:</p><ol><li>use the JAR file provided in <code>test/</code>, or download the &quot;all-in-one&quot; JAR (e.g. version <code>1.7</code>) from Maven Central,</li><li>update the target URL in <code>test/test-run-props.xml</code> if required,</li><li>run <code>java -jar ets-ogcapi-features10-1.7-aio.jar -o /path/to/output -h /path/to/test-run-props.xml</code>.</li></ol><p>A useful tool to check OpenAPI specification conformance is <a href="https://github.com/Redocly/redocly-cli" target="_blank" rel="noreferrer">redocly-cli</a>.</p><h2 id="building" tabindex="-1">Building <a class="header-anchor" href="#building" aria-label="Permalink to &quot;Building&quot;">​</a></h2><p>Build the Docker image:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your-image-nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><p>The project is also configured to use <strong>GitHub Actions</strong> to build and push the image to <a href="https://hub.docker.com/u/kalisio/" target="_blank" rel="noreferrer">Kalisio&#39;s Docker Hub</a>. The image is tagged using the <code>version</code> property of <code>package.json</code>. See the <a href="https://github.com/kalisio/development" target="_blank" rel="noreferrer">Kalisio development toolkit</a> for details.</p><h2 id="deploying" tabindex="-1">Deploying <a class="header-anchor" href="#deploying" aria-label="Permalink to &quot;Deploying&quot;">​</a></h2><p>The image is designed to be deployed with the <a href="https://kalisio.github.io/kargo/" target="_blank" rel="noreferrer">Kargo</a> project.</p><h2 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to &quot;License&quot;">​</a></h2><p>Licensed under the <a href="https://opensource.org/licenses/MIT" target="_blank" rel="noreferrer">MIT License</a>.</p>`,39)])])}const g=s(o,[["render",r]]);export{k as __pageData,g as default};
